"""Exact 600-frame school-warning motion requests for prospective Native capture.

These are controller targets. The source meter must use observed poses, speeds,
warning actors, children, and release, not these requested values.
"""

from __future__ import annotations

import math

from school_warning_scene import CASES, FEET_PER_METRE, controller_command, scene_request, validate_request


FRAMES = 600
STOP_FRAME = 120
RELEASE_FRAME = 250
ARRIVAL_FRAME = 400
START_X_M = -65.0
END_X_M = 20.0


def plan(suffix):
    if suffix not in CASES:
        raise ValueError("Unknown exact school-warning case")
    request = scene_request(suffix)
    validate_request(request)
    stop_x = request["vehicle"]["requested_stop_center_x_m"]
    rows = []
    for index in range(FRAMES):
        if index < STOP_FRAME:
            target = START_X_M + (stop_x - START_X_M) * index / STOP_FRAME
            phase = "approach_stop"
        elif index < RELEASE_FRAME:
            target = stop_x
            phase = "hold_for_observed_release"
        elif index < ARRIVAL_FRAME:
            target = stop_x + (END_X_M - stop_x) * (index - RELEASE_FRAME) / (ARRIVAL_FRAME - RELEASE_FRAME)
            phase = "release_request_pending_source_review"
        else:
            target = END_X_M
            phase = "end_hold"
        rows.append({"frame": index, "time_s": index / 20,
                     "target_center_x_m": target, "target_y_m": -1.75,
                     "phase": phase,
                     "requested_warning_active": index < RELEASE_FRAME,
                     "requested_child_about_to_cross": index < RELEASE_FRAME,
                     "requested_signal_release": index == RELEASE_FRAME})
    return rows


def check_pair():
    first, second = plan("probe_1"), plan("probe_2")
    if len(first) != FRAMES or len(second) != FRAMES:
        raise ValueError("Exact 30-second request missing")
    if first[0]["target_center_x_m"] != START_X_M or second[0]["target_center_x_m"] != START_X_M:
        raise ValueError("Shared approach start differs")
    fixed = ("frame", "time_s", "target_y_m", "phase", "requested_warning_active",
             "requested_child_about_to_cross", "requested_signal_release")
    for index, (left, right) in enumerate(zip(first, second)):
        if any(left[key] != right[key] for key in fixed):
            raise ValueError("Fixed request policy differs at " + str(index))
        if not all(math.isfinite(item["target_center_x_m"]) for item in (left, right)):
            raise ValueError("Nonfinite Native target")
    for suffix, rows in (("probe_1", first), ("probe_2", second)):
        target = -CASES[suffix] / FEET_PER_METRE
        if any(abs(rows[index]["target_center_x_m"] - target) > 1e-9
               for index in range(STOP_FRAME, RELEASE_FRAME)):
            raise ValueError("Hold position differs")
    return {"case_suffixes": ["probe_1", "probe_2"],
            "frames": FRAMES, "rate_hz": 20,
            "hold_interval": [STOP_FRAME, RELEASE_FRAME],
            "requested_stop_center_ft": dict(CASES),
            "only_variable": "requested_stop_center_station",
            "physical_completion": None, "legal_outcome": None}


def command_for_observation(suffix, frame, observed_center_x_m, observed_speed_mps,
                            warning_active, observed_release):
    """Use observed release, never the request row, to authorize departure."""
    if frame >= RELEASE_FRAME and observed_release is None:
        stop_x = -CASES[suffix] / FEET_PER_METRE
        if observed_center_x_m >= stop_x - 1.0:
            return {"phase": "hold_pending_original_release", "throttle": 0.0,
                    "brake": 1.0, "steer": 0.0}
    return controller_command(suffix, frame, observed_center_x_m,
                              observed_speed_mps, warning_active, observed_release)


class SchoolController:
    """Stateful controller whose release latch requires an earlier observed stop."""

    def __init__(self, suffix):
        if suffix not in CASES:
            raise ValueError("Unknown exact school-warning case")
        self.suffix = suffix
        self.stopped_under_warning = False
        self.released_after_stop = False

    def step(self, frame, observed_center_x_m, observed_speed_mps,
             warning_active, observed_release):
        target = -CASES[self.suffix] / FEET_PER_METRE
        if (warning_active is True and observed_speed_mps <= 0.10 and
                abs(observed_center_x_m - target) <= 2.0):
            self.stopped_under_warning = True
        if observed_release is not None and self.stopped_under_warning:
            self.released_after_stop = True
        release = observed_release if self.released_after_stop else None
        command = command_for_observation(self.suffix, frame, observed_center_x_m,
                                          observed_speed_mps, warning_active, release)
        if not self.stopped_under_warning and command["phase"] == "released":
            raise ValueError("Controller released without observed prior stop")
        return command

"""Authored school pedestrian lane, warning device, child and ego requests."""

from __future__ import annotations

import json
import math
import xml.etree.ElementTree as ET


ROAD_ID = 394563
ROAD_START_X_M = -100
ROAD_LENGTH_M = 200
LANE_WIDTH_M = 3.5
LANE_NEAR_SIDE_X_M = 0.0
FEET_PER_METRE = 3.280839895013123
CASE_VARIANTS = {
    "probe_1": (55.0, "signal_device", "signal_removed"),
    "probe_2": (40.0, "signal_device", "signal_removed"),
    "signal_stopped": (55.0, "signal_device", "signal_stopped"),
    "signal_raised": (55.0, "signal_device", "signal_raised"),
    "flagman_go": (55.0, "flagman", "flagman_go"),
    "flagman_left": (55.0, "flagman", "flagman_left"),
    "person_go": (55.0, "other_person", "person_go"),
    "person_left": (55.0, "other_person", "person_left"),
}
CASES = {name: specification[0] for name, specification in CASE_VARIANTS.items()}
CAMERAS = {"overview", "approach", "reference_corner", "driver_reference"}
RELEASES = {"signal_stopped", "signal_raised", "signal_removed",
            "flagman_go", "flagman_left", "person_go", "person_left"}


def open_drive():
    root = ET.Element("OpenDRIVE")
    ET.SubElement(root, "header", revMajor="1", revMinor="4",
                  name="C394563-school-warning-road", version="1",
                  north="15", south="-15", east="100", west="-100",
                  vendor="full-train-worker")
    road = ET.SubElement(root, "road", id=str(ROAD_ID), name="C394563_school_lane_approach",
                         length=str(ROAD_LENGTH_M), junction="-1")
    ET.SubElement(road, "link")
    geometry = ET.SubElement(ET.SubElement(road, "planView"), "geometry",
                             s="0", x=str(ROAD_START_X_M), y="0", hdg="0",
                             length=str(ROAD_LENGTH_M))
    ET.SubElement(geometry, "line")
    ET.SubElement(ET.SubElement(road, "elevationProfile"), "elevation",
                  s="0", a="0", b="0", c="0", d="0")
    lanes = ET.SubElement(road, "lanes")
    ET.SubElement(lanes, "laneOffset", s="0", a="0", b="0", c="0", d="0")
    section = ET.SubElement(lanes, "laneSection", s="0")
    for side, ident in (("left", 1), ("center", 0), ("right", -1)):
        group = ET.SubElement(section, side)
        lane = ET.SubElement(group, "lane", id=str(ident),
                             type="none" if ident == 0 else "driving", level="false")
        if ident:
            ET.SubElement(lane, "width", sOffset="0", a=str(LANE_WIDTH_M), b="0", c="0", d="0")
        ET.SubElement(lane, "roadMark", sOffset="0",
                      type="solid" if ident == 0 else "broken",
                      color="yellow" if ident == 0 else "white", width="0.12")
    ET.SubElement(road, "objects")
    ET.SubElement(road, "signals")
    return ET.tostring(root, encoding="unicode")


def scene_request(case, *, vehicle_blueprint="vehicle.tesla.model3",
                  warning_blueprint="static.prop.warning",
                  child_blueprint="walker.pedestrian.0001"):
    if case not in CASES:
        raise ValueError("Unknown school warning comparison case")
    if not vehicle_blueprint.startswith("vehicle."):
        raise ValueError("Invalid vehicle blueprint")
    role = CASE_VARIANTS[case][1]
    if role == "signal_device" and not warning_blueprint.startswith("static.prop."):
        raise ValueError("Invalid warning device prop blueprint")
    if role != "signal_device" and not warning_blueprint.startswith("walker.pedestrian."):
        warning_blueprint = "walker.pedestrian.0001"
    if not child_blueprint.startswith("walker.pedestrian."):
        raise ValueError("Invalid child actor blueprint request")
    return {
        "format": "worker-authored-school-warning-request", "case": case,
        "road_opendrive": open_drive(), "road_id": ROAD_ID,
        "vehicle": {"blueprint": vehicle_blueprint, "start_xyz": [-65, -1.75, 0.5],
                    "heading_deg": 0,
                    "requested_stop_center_x_m": LANE_NEAR_SIDE_X_M - CASES[case] / FEET_PER_METRE},
        "school_pedestrian_lane": {"near_side_x_m": LANE_NEAR_SIDE_X_M,
                                   "far_side_x_m": 4.0, "official_status_verified": False},
        "warning": {"role": role, "blueprint": warning_blueprint,
                    "xyz": [-1, -6, 0], "active_from_frame": 0,
                    "requested_release_event": CASE_VARIANTS[case][2],
                    "requested_release_frame": 250,
                    "original_warning_state_verified": False},
        "child": {"blueprint": child_blueprint, "start_xyz": [-2, -8, 0.2],
                  "age_status_verified": False, "requested_about_to_cross": True},
        "cameras": [
            {"name": "overview", "xyz": [-18, -13, 24], "yaw": 35, "pitch": -50, "size": [1920, 1080]},
            {"name": "approach", "xyz": [-3, -11, 8], "yaw": 90, "pitch": -20, "size": [1280, 720]},
            {"name": "reference_corner", "xyz": [6, 11, 8], "yaw": 180, "pitch": -20, "size": [1280, 720]},
            {"name": "driver_reference", "xyz": [1, 0, 2], "yaw": 0, "pitch": -8, "size": [1280, 720], "attach_to_vehicle": True},
        ],
        "rate_hz": 20, "duration_s": 30, "planned_frames": 600,
        "physical_success_claimed": False,
    }


def controller_command(case, frame, observed_x_m, observed_speed_mps, warning_active, observed_release):
    if case not in CASES or type(frame) is not int or not 0 <= frame < 600:
        raise ValueError("Invalid warning case or frame")
    if any(isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value)
           for value in (observed_x_m, observed_speed_mps)) or observed_speed_mps < 0:
        raise ValueError("Missing original Native pose or speed")
    if warning_active not in (True, False) or observed_release not in RELEASES | {None}:
        raise ValueError("Missing sourced warning or release")
    target = LANE_NEAR_SIDE_X_M - CASES[case] / FEET_PER_METRE
    remaining = target - observed_x_m
    if remaining < -1.0 and observed_release is None:
        raise ValueError("Vehicle overshot requested stop before release")
    if observed_release is not None:
        return {"phase": "released", "throttle": 0.20, "brake": 0.0, "steer": 0.0}
    if warning_active and remaining <= max(1.0, observed_speed_mps ** 2 / 4 + 1.0):
        return {"phase": "brake_or_hold", "throttle": 0.0, "brake": 1.0, "steer": 0.0}
    if warning_active:
        return {"phase": "approach", "throttle": 0.20, "brake": 0.0, "steer": 0.0}
    return {"phase": "await_sourced_release", "throttle": 0.0, "brake": 1.0, "steer": 0.0}


def validate_request(request):
    root = ET.fromstring(request["road_opendrive"])
    road = root.find("road")
    if root.tag != "OpenDRIVE" or road is None or road.attrib["id"] != str(ROAD_ID):
        raise ValueError("Authored school road identity missing")
    lanes = road.findall("lanes/laneSection/*/lane")
    if {lane.attrib["id"] for lane in lanes} != {"-1", "0", "1"}:
        raise ValueError("Two-way road lanes missing")
    if {camera["name"] for camera in request.get("cameras", [])} != CAMERAS:
        raise ValueError("Four source camera requests missing")
    if request.get("rate_hz") != 20 or request.get("planned_frames") != 600:
        raise ValueError("30-second capture contract missing")
    if request["warning"]["original_warning_state_verified"] or request["child"]["age_status_verified"]:
        raise ValueError("Authored request cannot assert source verification")
    return {"case": request["case"], "camera_count": 4,
            "planned_frames": 600, "authored_geometry_checked": True,
            "native_warning_and_child_verified": False}


if __name__ == "__main__":
    print(json.dumps({case: validate_request(scene_request(case)) for case in CASES}, indent=2))

"""Source-bound 30-second school-lane warning, stop and release measurement."""

from __future__ import annotations

import argparse
import json
import math
from pathlib import Path


FRAMES = 600
RATE_HZ = 20
FEET_PER_METRE = 3.280839895013123
CAMERAS = {"overview", "approach", "reference_corner", "driver_reference"}
WARNING_ROLES = {"signal_device", "flagman", "other_person"}
RELEASES = {"signal_stopped", "signal_raised", "signal_removed",
            "flagman_go", "flagman_left", "person_go", "person_left"}


def finite(value, name):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ValueError(f"Invalid {name}")
    return float(value)


def sha(value, name):
    if not isinstance(value, str) or len(value) != 64 or any(c not in "0123456789abcdef" for c in value):
        raise ValueError(f"Missing source hash: {name}")


def measure(context, rows):
    if context.get("source_kind") != "original_native_school_warning_readback":
        raise ValueError("Original school warning source missing")
    for name in ("native_map_sha256", "school_lane_geometry_sha256", "vehicle_extent_sha256",
                 "warning_actor_sha256", "warning_state_source_sha256", "child_presence_source_sha256"):
        sha(context.get(name), name)
    if context.get("school_pedestrian_lane_survey") is not True:
        raise ValueError("School pedestrian lane not sourced")
    lane_near_x = finite(context.get("nearest_lane_side_x_m"), "nearest lane side")
    length = finite(context.get("vehicle_length_m"), "vehicle length")
    if length <= 0:
        raise ValueError("Vehicle extent invalid")
    if len(rows) != FRAMES:
        raise ValueError("Incomplete 30-second Native trace")
    previous_native = None
    centers, speeds, warning, releases = [], [], [], []
    roles = set()
    for index, row in enumerate(rows):
        if not isinstance(row, dict) or row.get("video_frame") != index:
            raise ValueError("Video frame identity gap")
        native = row.get("native_frame")
        if type(native) is not int or (previous_native is not None and native <= previous_native):
            raise ValueError("Native frame identity gap")
        previous_native = native
        if abs(finite(row.get("time_s"), "Native time") - index / RATE_HZ) > 1e-6:
            raise ValueError("Native time join failed")
        cameras = row.get("source_cameras")
        if not isinstance(cameras, dict) or set(cameras) != CAMERAS or any(cameras[c] != index for c in CAMERAS):
            raise ValueError("Four source camera frame join failed")
        center = finite(row.get("vehicle_center_x_m"), "vehicle center")
        speed = finite(row.get("observed_speed_mps"), "observed speed")
        if speed < 0:
            raise ValueError("Negative speed")
        role = row.get("warning_role")
        if role not in WARNING_ROLES:
            raise ValueError("Warning actor role missing")
        roles.add(role)
        if row.get("warning_active") not in (True, False):
            raise ValueError("Warning state source missing")
        if row.get("children_about_to_cross_or_crossing") not in (True, False):
            raise ValueError("Children warning context missing")
        release = row.get("release_event")
        if release is not None and release not in RELEASES:
            raise ValueError("Unknown statutory release event")
        allowed = {"signal_device": {"signal_stopped", "signal_raised", "signal_removed"},
                   "flagman": {"flagman_go", "flagman_left"},
                   "other_person": {"person_go", "person_left"}}
        if release is not None and release not in allowed[role]:
            raise ValueError("Release event and warning role differ")
        centers.append(center)
        speeds.append(speed)
        warning.append(row["warning_active"] and row["children_about_to_cross_or_crossing"])
        releases.append(release)
    if len(roles) != 1:
        raise ValueError("Warning actor changed within comparison")
    if not any(warning):
        raise ValueError("No sourced warning of children")
    stop_frames = [i for i in range(1, FRAMES - 1)
                   if warning[i] and speeds[i - 1] <= 0.10 and speeds[i] <= 0.10 and speeds[i + 1] <= 0.10]
    if not stop_frames:
        raise ValueError("No observed complete cessation under warning")
    stop = stop_frames[0]
    first_release = next((i for i, event in enumerate(releases) if event is not None), None)
    first_proceed = next((i for i in range(stop + 1, FRAMES)
                          if speeds[i] > 0.10 and centers[i] > centers[stop] + 0.5), None)
    front = lane_near_x - (centers[stop] + length / 2)
    centre = lane_near_x - centers[stop]
    rear = lane_near_x - (centers[stop] - length / 2)
    return {
        "format": "worker-source-school-warning-stop-measurement",
        "frame_count": FRAMES, "rate_hz": RATE_HZ,
        "warning_role": next(iter(roles)),
        "first_stop_frame": stop,
        "stop_distance_to_nearest_school_lane_side_ft": {
            "front": front * FEET_PER_METRE,
            "centre": centre * FEET_PER_METRE,
            "rear": rear * FEET_PER_METRE,
        },
        "first_release_frame": first_release,
        "first_release_event": releases[first_release] if first_release is not None else None,
        "first_proceed_frame": first_proceed,
        "proceeded_before_observed_release": first_proceed is not None and (first_release is None or first_proceed < first_release),
        "statutory_stop_distance_ft": 50,
        "legal_compliance": "unassessed",
        "limitations": [
            "Stop detector is an engineering threshold, not a legal minimum duration",
            "The statute does not select a front, centre, or rear vehicle reference point",
            "Release and child-warning meaning require original actor and pixel review",
            "Commanded release cannot substitute for an observed source event",
        ],
    }


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--context", type=Path, required=True)
    parser.add_argument("--trace", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    rows = [json.loads(line) for line in args.trace.read_text().splitlines() if line]
    args.output.write_text(json.dumps(measure(json.loads(args.context.read_text()), rows), indent=2, allow_nan=False) + "\n")


if __name__ == "__main__":
    main()

import unittest
from runner import check
from finalize import derive
class ExactSchoolWarning(unittest.TestCase):
 def test_selected_native_request(self):
  self.assertEqual(check()['pair']['frames'],600)
  self.assertFalse(check()['original_native_observed'])
 def test_missing_original_source_rejected(self):
  with self.assertRaisesRegex(ValueError,'Missing sealed original'):
   derive('.')
